input.command:
cat > UITests/ControlUITests.swift <<'EOF'
import XCTest

final class ControlUITests: XCTestCase {
    func testSearchForTestAndSelectPeople() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let openButton = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 2) {
            openButton.tap()
        }

        bluesky.activate()
        let searchForTest = bluesky.descendants(matching: .any)
            .matching(NSPredicate(format: "label CONTAINS %@", "Search for \"test\"")).firstMatch
        if searchForTest.waitForExistence(timeout: 3) {
            searchForTest.tap()
        } else {
            print("BLUESKY BEFORE SEARCH:\n\(bluesky.debugDescription)")
            let keyboardSearch = bluesky.keyboards.buttons["search"]
            XCTAssertTrue(keyboardSearch.waitForExistence(timeout: 5), bluesky.debugDescription)
            keyboardSearch.tap()
        }

        print("SEARCH RESULTS:\n\(bluesky.debugDescription)")
        let people = bluesky.descendants(matching: .any)
            .matching(NSPredicate(format: "label == %@", "People")).firstMatch
        XCTAssertTrue(people.waitForExistence(timeout: 15), bluesky.debugDescription)
        people.tap()
        print("PEOPLE RESULTS:\n\(bluesky.debugDescription)")
        XCTAssertTrue(people.isHittable, bluesky.debugDescription)
    }
}
EOF
